const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',news:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 8h10M7 12h4M7 16h4M15 12h2M15 16h2"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h15V8H5a3 3 0 0 1 0-5"/><path d="M20 12h-6v5h6M16 14.5h1"/>',spark:'<path d="m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3ZM20 2v4M18 4h4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3ZM9 12l2 2 4-4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="m3 17 7-7 4 4 7-10M14 4h7v7"/>',plus:'<path d="M12 5v14M5 12h14"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const $=s=>document.querySelector(s),escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const dateLabel=value=>{if(!value||!Number.isFinite(new Date(value).getTime()))return 'ไม่ระบุเวลา';return new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value))+' น. (ไทย)';};
let stocks=[];
const stock=symbol=>stocks.find(s=>s.symbol===symbol)||{symbol,name:symbol,thai:'บริษัทที่ติดตาม',currency:'USD',sector:'',url:'#'};
function companyLogo(symbol){const company=stock(symbol),label=escapeHtml(symbol.slice(0,3));return `<span class="company-logo${company.icon?' has-icon':''}" title="${escapeHtml(company.name)}">${label}${company.icon?`<img src="${escapeHtml(company.icon)}" alt="" loading="lazy" decoding="async">`:''}</span>`;}
document.addEventListener('error',event=>{if(event.target.matches?.('.company-logo img')){event.target.parentElement.classList.remove('has-icon');event.target.remove();}},true);
const defaults={watchlist:[],alerts:{daily:true,news:true,trend:true,time:'08:00',scope:'watchlist'},sources:[]};
let state=structuredClone(defaults),committedState=structuredClone(defaults),currentUser=null,stateRevision=0,isSaving=false;
let page='overview',newsFilter='all',selectedStock='AAPL',query='',toastTimer;
let newsData={items:[],sources:[]},newsLoading=false,newsError='',newsEpoch=0;
let aiStatus={enabled:true,available:false,model:'qwen3:8b'},aiSummaries={},aiAnswers={},aiDrafts={},aiBusy=false,aiQuestionBusy=false,aiError='',aiQuestionError='',aiEpoch=0;
let forecasts={},forecastLoading='',forecastEpoch=0;
function resetForecast(){forecastEpoch++;forecasts={};forecastLoading='';}
async function loadForecast(symbol=selectedStock){
 if(!currentUser||forecasts[symbol]||forecastLoading===symbol)return;
 const epoch=forecastEpoch,userId=currentUser.id;forecastLoading=symbol;if(page==='insights')render();
 try{const result=await api('/api/forecast?symbol='+encodeURIComponent(symbol),{timeout:20000});if(epoch!==forecastEpoch||currentUser?.id!==userId)return;forecasts[symbol]=result;}
 catch(error){if(epoch!==forecastEpoch)return;forecasts[symbol]={status:'error',error:error.message};if(error.status===401)showSignedOut('login');}
 finally{if(epoch===forecastEpoch){forecastLoading='';if(currentUser&&page==='insights')render();}}
}
async function save(){
  if(isSaving||!currentUser)return false;
  isSaving=true;
  try{
    const result=await api('/api/state',{method:'PUT',body:{state,userId:currentUser.id,revision:stateRevision}});
    const watchlistChanged=JSON.stringify(committedState.watchlist)!==JSON.stringify(result.state.watchlist);state=result.state;stateRevision=result.revision;committedState=structuredClone(state);if(watchlistChanged)loadQuotes();return true;
  }catch(error){
    state=structuredClone(committedState);
    if(error.status===401)showSignedOut('login');
    if(error.status===409){
      try{const latest=await api('/api/session');if(!latest.user||latest.user.id!==currentUser?.id)showSignedOut('login');else{state=latest.state;stateRevision=latest.revision;committedState=structuredClone(state);if($('#modal').open)$('#modal').close();render();}}catch{showSignedOut('login');}
    }
    toast(error.message);return false;
  }finally{isSaving=false}
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}

function resetNews(){newsEpoch++;newsLoading=false;newsData={items:[],sources:[]};newsError='';}
async function loadNews({redraw=true}={}){
 if(!currentUser||newsLoading)return;const userId=currentUser.id,epoch=++newsEpoch;newsLoading=true;newsError='';
 try{const result=await api('/api/news');if(epoch!==newsEpoch||currentUser?.id!==userId)return;newsData=result;}
 catch(error){if(epoch!==newsEpoch)return;newsError=error.message;if(error.status===401)showSignedOut('login');}
 finally{if(epoch===newsEpoch){newsLoading=false;if(redraw&&currentUser&&['overview','news','alerts','insights'].includes(page))render();}}
}
function resetAI(){aiEpoch++;aiStatus={enabled:true,available:false,provider:'ollama',online:false,model:'qwen3:8b'};aiSummaries={};aiAnswers={};aiDrafts={};aiBusy=false;aiQuestionBusy=false;aiError='';aiQuestionError='';}
async function loadAIStatus(){
 if(!currentUser)return;const userId=currentUser.id,epoch=++aiEpoch;
 try{const result=await api('/api/ai/status');if(epoch!==aiEpoch||currentUser?.id!==userId)return;aiStatus=result;}
 catch(error){if(epoch!==aiEpoch)return;aiStatus={enabled:true,available:false,provider:'ollama',online:false,model:'qwen3:8b'};if(error.status===401)showSignedOut('login');}
 finally{if(epoch===aiEpoch&&currentUser&&['overview','insights'].includes(page))render();}
}
async function runAISummary(){
 if(!currentUser||aiBusy)return;const userId=currentUser.id,epoch=aiEpoch,symbol=selectedStock;aiBusy=true;aiError='';render();
 try{const result=await api('/api/ai/summary',{method:'POST',body:{symbol},timeout:125000});if(epoch!==aiEpoch||currentUser?.id!==userId)return;aiSummaries[symbol]=result;aiAnswers[symbol]=[];}
 catch(error){if(epoch!==aiEpoch)return;aiError=error.message;if(error.status===401)showSignedOut('login');}
 finally{if(epoch===aiEpoch){aiBusy=false;if(currentUser)render();}}
}
async function askAI(question){
 if(!currentUser||aiQuestionBusy)return;
 const symbol=selectedStock,summary=aiSummaries[symbol],userId=currentUser.id,epoch=aiEpoch;
 if(!summary?.articles?.length)return;
 aiQuestionBusy=true;aiQuestionError='';render();
 try{const answer=await api('/api/ai/ask',{method:'POST',body:{symbol,question,articleIds:summary.articles.map(article=>article.id)},timeout:125000});if(epoch!==aiEpoch||currentUser?.id!==userId)return;aiAnswers[symbol]=[...(aiAnswers[symbol]||[]),answer].slice(-3);aiDrafts[symbol]='';}
 catch(error){if(epoch!==aiEpoch)return;if(selectedStock===symbol)aiQuestionError=error.message;if(error.status===401)showSignedOut('login');}
 finally{if(epoch===aiEpoch){aiQuestionBusy=false;if(currentUser)render();}}
}
function header(title,sub,action=''){return `<div class="page-header"><div><div class="eyebrow">YOUR US MARKET WORKSPACE</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${action}</div></div>`;}
const addButton=()=>`<button class="btn primary" data-action="add">${icon('plus')} เลือกบริษัทที่ติดตาม</button>`;
function newsItem(n){return `<article class="news-card">${n.symbol?companyLogo(n.symbol):'<span class="company-logo">US</span>'}<div><div class="news-meta"><span class="ticker-tag">${escapeHtml(n.symbol||'ภาพรวมสหรัฐฯ')}</span><span>${escapeHtml(n.source)}</span>${n.stale?'<span class="sentiment negative">ข้อมูลเก่า · อัปเดตไม่สำเร็จ/ล่าช้า</span>':''}</div><a class="news-title" href="${escapeHtml(n.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(n.title)} ↗</a><div class="news-footer"><span>เผยแพร่ ${escapeHtml(dateLabel(n.publishedAt))}</span><span>${n.sourceType==='finance'?'สื่อการเงิน · ผ่าน Finnhub':n.sourceType==='macro'?'ข่าวเศรษฐกิจ · RSS ทางการ':'ประกาศบริษัท'} · อ่านต้นฉบับ</span></div></div></article>`;}
function feedStatus(){return `<details class="feed-status"><summary>สถานะแหล่งข่าว ${newsData.sources.filter(s=>s.status==='ok').length}/${newsData.sources.length} เชื่อมต่อสำเร็จ</summary>${newsData.sources.map(s=>`<p><b>${escapeHtml(s.name)}</b> · ${s.status==='ok'?'เชื่อมต่อแล้ว':s.status==='error'?'เชื่อมต่อไม่สำเร็จ':'รอข้อมูล'}${s.enabled?'':' · ปิดในบัญชีนี้'}<br><small>ดึงข้อมูลสำเร็จล่าสุด ${escapeHtml(dateLabel(s.succeededAt))}${s.error?' · '+escapeHtml(s.error):''}</small></p>`).join('')}<p>ตรวจทุก 15 นาทีขณะเซิร์ฟเวอร์ทำงาน เวลาเผยแพร่ข่าวอาจเก่ากว่าเวลาที่ดึงข้อมูล</p></details>`;}
function newsSection(compact=false){const items=newsData.items.filter(n=>newsFilter!=='watchlist'||state.watchlist.includes(n.symbol));return `<section class="card"><div class="section-title"><h2>ข่าวบริษัทและสื่อการเงิน</h2><button class="text-button" data-refresh-news ${newsLoading?'disabled':''}>${newsLoading?'กำลังโหลด…':'รีเฟรช'}</button></div><div class="tabs"><button class="tab ${newsFilter==='all'?'active':''}" data-filter="all">แหล่งข่าวที่เปิดไว้</button><button class="tab ${newsFilter==='watchlist'?'active':''}" data-filter="watchlist">บริษัทที่ฉันเลือก</button></div>${newsError?`<p role="alert" class="form-error">${escapeHtml(newsError)}</p>`:''}${(compact?items.slice(0,5):items).map(newsItem).join('')||`<div class="empty">${newsLoading?'กำลังโหลดข่าว…':'ยังไม่มีข่าวในรายการนี้'}<br><small>ข่าวการเงินต้องใช้ Finnhub key; แหล่งที่คุณเปิดไว้จะแสดงสถานะด้านล่าง</small></div>`}${feedStatus()}<p class="small-note">หัวข้อจาก RSS บริษัท ฟีดเศรษฐกิจที่ตรวจสอบแล้ว และสื่อการเงินผ่าน Finnhub กด AI Insights เพื่อสรุปจากหัวข้อพร้อมลิงก์ต้นฉบับ ข่าวและความเห็นจากสื่อควรตรวจสอบก่อนตัดสินใจ</p></section>`;}
function aiList(title,items){return items?.length?`<div class="ai-detail"><b>${escapeHtml(title)}</b><ul>${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul></div>`:'';}
function aiAnswerCard(item){return `<article class="ai-answer"><div class="ai-answer-meta"><b>คุณถาม: ${escapeHtml(item.question)}</b><time datetime="${escapeHtml(item.answeredAt)}">AI ตอบ ${escapeHtml(dateLabel(item.answeredAt))}</time></div><p>${escapeHtml(item.answer)}</p>${item.sources?.length?`<div class="ai-answer-sources"><b>หัวข้อข่าวอ้างอิง</b>${item.sources.map(source=>`<a href="${escapeHtml(source.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(source.source)} · ${escapeHtml(source.title)} · ${escapeHtml(dateLabel(source.publishedAt))} ↗</a>`).join('')}</div>`:''}</article>`;}
function aiCard(){
 const result=aiSummaries[selectedStock],available=aiStatus.enabled&&aiStatus.available,online=aiStatus.provider==='groq',status=available?(online?'Groq ออนไลน์พร้อมใช้':'Ollama พร้อมใช้ในเครื่อง'):aiStatus.enabled?(online&&aiStatus.configured===false?'ยังไม่ได้ใส่ Groq key':online?'Groq ยังไม่พร้อม':'ยังไม่พบโมเดล'):'ปิดใช้งาน';
 const sources=result?.articles?.map(item=>`<a href="${escapeHtml(item.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(item.source)} · ${escapeHtml(item.title)}<small>เผยแพร่ ${escapeHtml(dateLabel(item.publishedAt))}${item.stale?' · ข่าวเก่า':''}</small></a>`).join('');
 const latest=result?.articles?.filter(item=>item.publishedAt).map(item=>new Date(item.publishedAt).getTime()).filter(Number.isFinite).sort((a,b)=>b-a)[0];
 const answers=aiAnswers[selectedStock]||[];
 return `<section class="ai-card"><div class="section-title"><h2>AI Insights</h2><span class="ai-badge">${escapeHtml(status)}</span></div><label class="field ai-stock">บริษัท<select id="ai-symbol">${stocks.map(s=>`<option ${s.symbol===selectedStock?'selected':''} value="${s.symbol}">${s.symbol} — ${s.name}</option>`).join('')}</select></label>${result?`<div class="ai-trend">${escapeHtml(result.title)}</div><div class="ai-timeline"><span>ข่าวล่าสุดที่ใช้: <b>${escapeHtml(dateLabel(latest))}</b></span><span>AI สรุปเมื่อ: <b>${escapeHtml(dateLabel(result.createdAt))}</b></span></div><p>${escapeHtml(result.summary)}</p><div class="ai-confidence">ความมั่นใจจากข้อมูล: ${result.confidence==='medium'?'ปานกลาง':'ต่ำ'} · ${result.provider==='groq'?'Groq ออนไลน์':'Ollama ในเครื่อง'} · ${escapeHtml(result.model)}${result.fallbackFrom?' · ใช้ตัวสำรองอัตโนมัติ':''}${result.cached?' · ใช้ผลสรุปเดิม':''}</div>${aiList('ข้อเท็จจริงจากหัวข้อ',result.facts)}${aiList('ปัจจัยเชิงบวกที่ควรตรวจต่อ',result.positiveFactors)}${aiList('ความเสี่ยง',result.risks)}${aiList('สิ่งที่ยังไม่ทราบ',result.unknowns)}${sources?`<div class="ai-sources"><b>หัวข้อข่าวที่ใช้</b>${sources}</div>`:''}<div class="ai-qa"><h3>ถามต่อจากข่าวชุดนี้</h3><p>ถามเกี่ยวกับบริษัทหรือข่าวที่แสดงด้านบน AI ใช้เฉพาะหัวข้อข่าว จึงอาจตอบรายละเอียดในบทความไม่ได้</p><form id="ai-question-form"><label class="field" for="ai-question">คำถามของคุณ</label><textarea id="ai-question" name="question" minlength="5" maxlength="300" rows="3" placeholder="เช่น ข่าวนี้พูดถึงความเสี่ยงอะไรบ้าง?" required>${escapeHtml(aiDrafts[selectedStock]||'')}</textarea><button class="btn primary" type="submit" ${!available||aiQuestionBusy?'disabled':''}>${aiQuestionBusy?'กำลังหาคำตอบ…':'ถาม AI'}</button></form>${aiQuestionError?`<p class="form-error" role="alert">${escapeHtml(aiQuestionError)}</p>`:''}${answers.map(aiAnswerCard).join('')}</div>`:`<div class="ai-trend">${available?'พร้อมสรุปหัวข้อข่าว':'ยังเริ่ม AI ไม่ได้'}</div><p>${available?'เลือกบริษัทแล้วให้ AI สรุปหัวข้อข่าวล่าสุดจากแหล่งที่เปิดไว้':online?'ใส่ GROQ_API_KEY ในไฟล์ .env แล้วเปิดเซิร์ฟเวอร์ใหม่':'ติดตั้งและเปิด Ollama พร้อมโมเดล '+escapeHtml(aiStatus.model)+' ตามคู่มือ AI'}</p>`}${aiError?`<p class="form-error" role="alert">${escapeHtml(aiError)}</p>`:''}<button class="btn full-button" data-ai-summary ${!available||aiBusy?'disabled':''}>${aiBusy?'AI กำลังวิเคราะห์…':'สรุปหัวข้อข่าวด้วย AI'}</button><div class="risk-inline">${online?'หัวข้อข่าวจะถูกส่งไป Groq เพื่อประมวลผล · ':''}วิเคราะห์จากหัวข้อข่าวเท่านั้น อาจขาดบริบท และไม่ใช่การทำนายราคา/คำแนะนำลงทุน</div></section>`;
}
function aiNotice(){const online=aiStatus.provider==='groq';return `<section class="card agent-notice"><div><h3>${online?'GroqCloud AI · ใช้อินเทอร์เน็ต':'Local AI · ประมวลผลในเครื่อง'}</h3><p>${online?'ส่งเฉพาะหัวข้อข่าว แหล่งข่าว เวลา และ ticker ไป Groq ไม่ส่งข้อมูลบัญชี':'ข้อมูลหัวข้อข่าวไม่ออกจากเครื่อง'} · ผลสรุปอ้างอิงเฉพาะแหล่งที่คุณเปิดไว้</p></div></section>`;}
function weeklyChart(history){
 const rows=Array.isArray(history)?history.filter(row=>/^\d{4}-\d{2}-\d{2}$/.test(row.date)&&Number.isFinite(row.close)&&row.close>0).slice(-104):[];
 if(rows.length<2)return '';
 const lows=rows.map(row=>row.close),min=Math.min(...lows),max=Math.max(...lows),range=max-min||1;
 const points=rows.map((row,index)=>`${(16+index*608/(rows.length-1)).toFixed(1)},${(150-(row.close-min)*128/range).toFixed(1)}`).join(' ');
 return `<figure class="weekly-chart"><figcaption>ราคาปิดรายสัปดาห์ย้อนหลัง · ปรับ split/ปันผล · USD</figcaption><svg viewBox="0 0 640 172" role="img" aria-label="กราฟราคาปิดรายสัปดาห์จาก ${escapeHtml(rows[0].date)} ถึง ${escapeHtml(rows.at(-1).date)}"><path d="M16 150H624" stroke="#dce5f0" stroke-width="2"/><polyline points="${points}" fill="none" stroke="#587fa9" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="chart-labels"><span>${escapeHtml(rows[0].date)} · ${money(rows[0].close)} USD</span><span>${escapeHtml(rows.at(-1).date)} · ${money(rows.at(-1).close)} USD</span></div></figure>`;
}
function forecastCard(){
 const result=forecasts[selectedStock],busy=forecastLoading===selectedStock;
 let message=busy?'กำลังตรวจข้อมูลราคาย้อนหลัง…':!result?'กำลังเตรียมข้อมูล…':result.status==='no_history'?(result.configured?'ยังไม่มีราคาย้อนหลังที่ใช้ได้':'ยังไม่ได้ใส่ ALPHAVANTAGE_API_KEY สำหรับราคาย้อนหลังฟรี'):result.status==='insufficient'?`มีข้อมูล ${result.available} สัปดาห์ ต้องการอย่างน้อย ${result.required} สัปดาห์`:result.status==='stale'?'ราคาย้อนหลังเก่าเกิน 14 วัน จึงงดให้สัญญาณ':result.status==='error'?'ตรวจแนวโน้มไม่สำเร็จ':result.status==='validated'?`สัญญาณทดลองสำหรับสัปดาห์หน้า: ${result.direction==='up'?'ขึ้น':'ลง'}`:result.backtest?.samples<100?'ช่วงทดสอบมีน้อยกว่า 100 สัปดาห์ จึงยังไม่แสดงสัญญาณ':result.backtest?.accuracy<0.6?'ความแม่นยำย้อนหลังต่ำกว่า 60% จึงไม่แสดงสัญญาณ':result.backtest?.accuracy<=result.backtest?.baselineAccuracy?'ผลย้อนหลังไม่ชนะการทายขึ้นเสมอ จึงไม่แสดงสัญญาณ':'ยังไม่แสดงสัญญาณ';
 const test=result?.backtest;
 return `<section class="card forecast-card"><div class="section-title"><h2>แนวโน้มจากราคาย้อนหลัง · ${escapeHtml(selectedStock)}</h2><span class="ai-badge">${result?.status==='validated'?'ผ่านเกณฑ์ย้อนหลัง':'ทดลอง'}</span></div><p class="forecast-trend">${escapeHtml(message)}</p>${weeklyChart(result?.history)}${test?`<p>แนวโน้มที่เกิดขึ้นแล้วใน 4 สัปดาห์: <b>${result.observedTrend==='up'?'ขึ้น':'ลง'}</b> (ไม่ใช่คำทำนาย)</p><p>มีราคาที่จบสัปดาห์แล้ว ${result.historyWeeks} สัปดาห์ · ทดสอบย้อนหลัง 5 ปี ${test.samples} สัปดาห์ · ถูก ${test.correct} สัปดาห์ (${Math.round(test.accuracy*100)}%) · ทายขึ้นเสมอ ${Math.round(test.baselineAccuracy*100)}%</p><p class="small-note">ราคาปิดปรับ split/ปันผลล่าสุด ${escapeHtml(result.asOf)} · ${money(result.latestClose)} USD · กฎแนวโน้ม 4 สัปดาห์ ทดสอบผลสัปดาห์ถัดไป</p>`:''}${result?.error?`<p class="small-note">${escapeHtml(result.error)}</p>`:''}<p class="risk-inline">ผลทดสอบย้อนหลังไม่รับประกันอนาคต ไม่ใช่คำแนะนำลงทุน และไม่ใช่ผลทำนายจาก Groq</p><button class="btn" data-refresh-forecast ${busy?'disabled':''}>${busy?'กำลังโหลด…':'ตรวจแนวโน้ม'}</button></section>`;
}
function renderOverview(){return header('มองข่าวสหรัฐฯ ให้เห็นภาพ','ข่าวจากบริษัทและแหล่งที่คุณเลือก',addButton())+`<div class="dashboard-columns"><div class="left-column"><section class="daily-brief"><div class="brief-top">YOUR NEWS PREFERENCES</div><h2>อยากให้เราติดตาม<br>ข่าวจากที่ไหนเป็นพิเศษ?</h2><p>เลือกบริษัทและเว็บไซต์ข่าวที่สนใจ โดยไม่ต้องบอกจำนวนหุ้นหรือต้นทุน<br>StockLens จะใช้ตัวเลือกนี้กรองข่าวและช่วยสรุปด้วย AI</p><div class="brief-bottom"><span>${state.watchlist.length} บริษัท · ${state.sources.filter(s=>s.enabled).length} แหล่งข่าวที่เปิด</span><button class="text-button" data-page="sources">เลือกแหล่งข่าว ${icon('arrow')}</button></div></section>${newsSection(true)}</div><div class="right-column"><section class="card"><span class="small-label">บริษัทที่อยากติดตามเป็นพิเศษ</span><div class="portfolio-amount">${state.watchlist.length}</div><p class="small-note">เก็บเฉพาะรายชื่อบริษัท<br>ไม่เก็บจำนวนหุ้น ต้นทุน หรือมูลค่าพอร์ต</p><button class="btn full-button" data-page="following">จัดการสิ่งที่ติดตาม</button></section>${aiCard()}</div></div>`;}
function renderFollowing(){return header('สิ่งที่ฉันอยากติดตาม','เลือกบริษัทเพื่อกรองข่าว ไม่ต้องกรอกข้อมูลพอร์ต',addButton())+`<section class="card"><div class="section-title"><h2>บริษัทที่เลือก</h2><span class="counter">${state.watchlist.length}</span></div><div class="company-grid">${state.watchlist.map(symbol=>{const s=stock(symbol);return `<article class="card company-card">${companyLogo(symbol)}<h3>${escapeHtml(symbol)}</h3><p>${escapeHtml(s.name)}<br>${escapeHtml(s.thai)} · ${escapeHtml(s.sector)}</p><button class="remove" data-unfollow="${escapeHtml(symbol)}">เลิกติดตาม</button></article>`;}).join('')||'<div class="empty">ยังไม่ได้เลือกบริษัท<br>กด “เลือกบริษัทที่ติดตาม” เพื่อบอกสิ่งที่คุณสนใจ</div>'}</div><a class="text-button" href="/api/export" download>ดาวน์โหลดข้อมูลบัญชี JSON ↗</a></section>`;}
function companyCards(){const q=query.trim().toLowerCase(),list=stocks.filter(s=>`${s.symbol} ${s.name} ${s.thai} ${s.sector}`.toLowerCase().includes(q));return list.map(s=>`<article class="card company-card">${companyLogo(s.symbol)}<h3>${escapeHtml(s.symbol)} <span class="unit">US · USD</span></h3><p>${escapeHtml(s.name)}<br>${escapeHtml(s.thai)} · ${escapeHtml(s.sector)}</p><button class="btn" data-company="${escapeHtml(s.symbol)}">ดูข้อมูลบริษัท ${icon('arrow')}</button></article>`).join('')||`<div class="empty">ไม่พบในรายชื่อ ${stocks.length} บริษัทที่รองรับ<br>ใช้ปุ่มค้นข่าวบนเว็บด้านบนเพื่อดูข่าวของบริษัทหรือหัวข้ออื่น</div>`;}
function webNewsActions(){const input=query.trim().slice(0,160);if(!input)return '<span class="small-note">พิมพ์ชื่อบริษัทหรือ ticker ด้านบนเพื่อเปิดข่าวจากเว็บค้นหา</span>';const company=stocks.find(stock=>stock.symbol.toLowerCase()===input.toLowerCase());const term=company?`${company.name} ${company.symbol}`:input;return `<a class="btn primary" href="https://news.google.com/search?q=${encodeURIComponent(term)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">ค้นใน Google News ↗</a><a class="btn" href="https://www.bing.com/news/search?q=${encodeURIComponent(term)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">ค้นใน Bing News ↗</a>`;}
function renderSearch(){return header('ค้นหาบริษัทและข่าวบนเว็บ','พิมพ์ชื่อบริษัท ตัวย่อหุ้น หรือหัวข้อข่าว')+`<label class="large-search">${icon('search')}<input id="company-query" type="search" placeholder="เช่น AVGO, Tesla, หุ้นญี่ปุ่น, AI" value="${escapeHtml(query)}" aria-label="ค้นหาบริษัทหรือข่าวบนเว็บ"></label><section class="card web-news-search"><h2>ค้นข่าวบนเว็บ</h2><p>ค้นได้ทุกคำ รวมบริษัทนอกแค็ตตาล็อก เปิดผลค้นหาจากเว็บไซต์ต้นทางในแท็บใหม่ ไม่ต้องใช้ API key</p><div id="web-news-actions" class="web-news-actions">${webNewsActions()}</div><p class="small-note">ผลขึ้นอยู่กับข่าวที่ผู้ให้บริการค้นหาจัดทำดัชนี ไม่รับประกันว่าครบทุกข่าว และข่าวนอก ${stocks.length} บริษัทจะยังไม่เข้าฟีดหรือ AI ของแอปโดยอัตโนมัติ</p></section><p class="small-note">บริษัทที่ติดตามในแอปได้: ${stocks.length} ตัวที่จดทะเบียนในสหรัฐฯ</p><div class="company-grid" id="company-results">${companyCards()}</div>`;}
function renderAlerts(){const a=state.alerts,items=a.news?newsData.items.filter(n=>a.scope==='all'||state.watchlist.includes(n.symbol)).slice(0,10):[];return header('ข่าวที่ติดตาม & การตั้งค่า','อ่านข่าวที่เกี่ยวข้องในแอป และจัดการบัญชี')+`<section class="card"><h2>ข่าวจากบริษัทที่คุณเลือก</h2>${items.map(newsItem).join('')||'<div class="empty">ยังไม่มีข่าวที่ตรงกับการตั้งค่า</div>'}<p class="small-note">ข่าวแสดงในแอป และส่ง Web Push ได้เมื่อเปิดรับบนอุปกรณ์และเซิร์ฟเวอร์ทำงาน ยังไม่มีอีเมลแจ้งข่าว</p></section><form id="alert-form" class="card settings"><div class="info-box">ตั้งค่าข่าวสำหรับแอปและ Web Push ได้ ส่วนสรุปรายวันและแจ้งแนวโน้มยังไม่เปิดส่งอัตโนมัติ</div>${[['news','แสดงและแจ้ง Push ข่าวบริษัทที่เลือก'],['daily','สรุปรายวัน · ยังไม่เปิดส่ง'],['trend','การเปลี่ยนแนวโน้ม AI · ยังไม่เปิดใช้']].map(([key,label])=>`<label class="setting-row"><span>${label}</span><input class="switch" type="checkbox" name="${key}" ${a[key]?'checked':''}></label>`).join('')}<label class="setting-row">เวลาที่ต้องการรับสรุป (เวลาไทย)<input type="time" name="time" required value="${escapeHtml(a.time)}"></label><label class="setting-row">ขอบเขตข่าว<select name="scope"><option value="watchlist" ${a.scope==='watchlist'?'selected':''}>บริษัทที่ฉันเลือก</option><option value="all" ${a.scope==='all'?'selected':''}>ทุกฟีดที่เปิดไว้</option></select></label><button class="btn primary" type="submit">บันทึกการตั้งค่า</button></form><section class="card settings"><h2>กู้คืนบัญชี</h2><p>เก็บรหัสกู้คืนไว้ในที่ปลอดภัย หากลืมรหัสผ่านใช้รหัสนี้ได้ การสร้างใหม่จะยกเลิกรหัสเดิม</p><button class="btn" data-new-recovery>สร้างรหัสกู้คืนใหม่</button></section>`;}
function render(){if(!currentUser)return;if(page==='portfolio')page='following';const names={overview:'ภาพรวม',news:'ข่าวสาร',following:'สิ่งที่ติดตาม',insights:'AI Insights',search:'ค้นหาบริษัท',alerts:'การแจ้งเตือน',sources:'แหล่งข้อมูล'};$('#breadcrumb').textContent=names[page];document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.page===page);if(n.dataset.page===page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});const views={overview:renderOverview,news:()=>header('ข่าวบริษัทและสื่อการเงิน','หัวข้อข่าวต้นทางพร้อมลิงก์และเวลาเผยแพร่')+newsSection(),following:renderFollowing,search:renderSearch,alerts:renderAlerts,sources:renderSourceManager,insights:()=>header('AI Insights','สรุปข่าวด้วย AI และตรวจแนวโน้มด้วยข้อมูลราคาย้อนหลัง')+`<div class="wide-ai">${aiNotice()}${aiCard()}${forecastCard()}</div>`};$('#main').innerHTML=views[page]();if(page==='search')$('#main .web-news-search').insertAdjacentHTML('beforebegin',researchPanel());if(['overview','following'].includes(page))$('#main').insertAdjacentHTML('beforeend',quotePanel());}
function navigate(next){if(!currentUser)return;page=next==='portfolio'?'following':next;history.replaceState(null,'','#'+page);render();if(page==='following')loadQuotes();if(page==='insights')loadForecast();window.scrollTo({top:0,behavior:'instant'});}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function addFollowing(symbol='AAPL'){openModal('เลือกบริษัทที่อยากให้ติดตาม',`<form id="following-form"><label class="field">บริษัท<select name="symbol">${stocks.filter(s=>!state.watchlist.includes(s.symbol)||s.symbol===symbol).map(s=>`<option value="${s.symbol}" ${s.symbol===symbol?'selected':''}>${s.symbol} — ${s.name}</option>`).join('')}</select></label><p class="form-help">เราเก็บเฉพาะชื่อบริษัทที่เลือก ไม่ขอจำนวนหุ้นหรือต้นทุน</p><button class="btn primary" type="submit">ติดตามข่าวบริษัทนี้</button></form>`);}
document.addEventListener('click',async e=>{
 if(!currentUser)return;const el=e.target.closest('button,a');if(!el)return;if(isSaving){toast('กำลังบันทึก กรุณารอสักครู่');return;}
 if(el.dataset.page)navigate(el.dataset.page);if(el.id==='quick-search'){navigate('search');$('#company-query').focus();}if(el.id==='close-modal')$('#modal').close();
 if(el.hasAttribute('data-ai-summary'))runAISummary();
 if(el.hasAttribute('data-refresh-forecast')){delete forecasts[selectedStock];loadForecast();}
 if(el.dataset.filter){newsFilter=el.dataset.filter;render();}if(el.hasAttribute('data-refresh-news')){loadNews();render();}if(el.dataset.action==='add')addFollowing();
 if(el.dataset.unfollow)openModal('เลิกติดตามบริษัท',`<p>เลิกติดตามข่าว ${escapeHtml(el.dataset.unfollow)}?</p><button class="btn primary" data-confirm-unfollow="${escapeHtml(el.dataset.unfollow)}">ยืนยันเลิกติดตาม</button>`);
 if(el.dataset.confirmUnfollow){state.watchlist=state.watchlist.filter(symbol=>symbol!==el.dataset.confirmUnfollow);const ok=await save();$('#modal').close();render();if(ok)toast('อัปเดตรายการที่ติดตามแล้ว');}
 if(el.dataset.company){const s=stock(el.dataset.company),followed=state.watchlist.includes(s.symbol);openModal(s.symbol+' · '+s.name,`<p>${escapeHtml(s.thai)} · ${escapeHtml(s.sector)}</p><p><a class="text-button" href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer">เว็บไซต์นักลงทุนสัมพันธ์ ↗</a></p><p><a class="text-button" href="https://news.google.com/search?q=${encodeURIComponent(`${s.name} ${s.symbol}`)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">ค้นข่าวบริษัทบนเว็บ ↗</a></p><p><a class="text-button" href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(s.symbol)}" target="_blank" rel="noopener noreferrer">ค้นเอกสารกับ SEC EDGAR ↗</a></p>${followed?'<div class="info-box">ติดตามข่าวบริษัทนี้แล้ว</div>':`<button class="btn primary" data-follow-symbol="${s.symbol}">ติดตามข่าวบริษัทนี้</button>`}`);}
 if(el.dataset.followSymbol){state.watchlist.push(el.dataset.followSymbol);if(await save()){selectedStock=el.dataset.followSymbol;$('#modal').close();render();toast('เพิ่มบริษัทที่ติดตามแล้ว');}}
 if(el.hasAttribute('data-new-recovery'))openModal('สร้างรหัสกู้คืนใหม่','<form id="new-recovery-form"><label class="field">ยืนยันรหัสผ่านปัจจุบัน<input type="password" name="password" autocomplete="current-password" maxlength="128" required></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">สร้างรหัสใหม่</button></form>');
});
document.addEventListener('input',e=>{if(e.target.id==='company-query'){query=e.target.value;$('#company-results').innerHTML=companyCards();$('#web-news-actions').innerHTML=webNewsActions();}if(e.target.id==='ai-question')aiDrafts[selectedStock]=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='ai-symbol'){selectedStock=e.target.value;aiQuestionError='';render();if(page==='insights')loadForecast();}});
document.addEventListener('submit',async e=>{
 if(!currentUser)return;const f=e.target;if(isSaving){e.preventDefault();return;}
 if(f.id==='ai-question-form'){e.preventDefault();const question=f.elements.question.value.trim();if(question.length>=5&&question.length<=300)askAI(question);return;}
 if(f.id==='following-form'){e.preventDefault();const symbol=f.elements.symbol.value;if(!state.watchlist.includes(symbol))state.watchlist.push(symbol);const ok=await save();$('#modal').close();render();if(ok){selectedStock=symbol;toast(`ติดตามข่าว ${symbol} แล้ว`);}}
 if(f.id==='alert-form'){e.preventDefault();state.alerts={daily:f.elements.daily.checked,news:f.elements.news.checked,trend:f.elements.trend.checked,time:f.elements.time.value,scope:f.elements.scope.value};if(await save()){render();toast('บันทึกการตั้งค่าแล้ว');}}
 if(f.id==='new-recovery-form'){e.preventDefault();const button=f.querySelector('button');if(button.disabled)return;button.disabled=true;try{const result=await api('/api/recovery-code',{method:'POST',body:{password:f.elements.password.value}});if(currentUser)openModal('เก็บรหัสกู้คืนใหม่',recoveryNotice(result.recoveryCode));}catch(error){f.querySelector('.form-error').textContent=error.message;}finally{button.disabled=false;}}
});
document.addEventListener('keydown',e=>{if(currentUser&&e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();navigate('search');$('#company-query').focus();}});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
setInterval(()=>{if(currentUser&&!isSaving&&document.visibilityState==='visible')loadNews({redraw:!$('#modal').open});},5*60*1000);
